CREATE COLUMN TABLE "TEST_AP"."TSI3" ("DocEntry" INTEGER CS_INT NOT NULL , "ObjType" INTEGER CS_INT, "LogInstanc" INTEGER CS_INT DEFAULT 0, "LineNum" INTEGER CS_INT NOT NULL , "RefDocEntr" INTEGER CS_INT, "RefDocNum" INTEGER CS_INT, "ExtDocNum" NVARCHAR(100), "RefObjType" NVARCHAR(20), "IssueDate" LONGDATE CS_LONGDATE, "Remark" NVARCHAR(254), "CardCode" NVARCHAR(15), PRIMARY KEY ("DocEntry", "LineNum")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "TSI3_DOC_ENTRY" ON "TEST_AP"."TSI3" ( "DocEntry" ASC )